import React, { useState, useEffect, useRef } from 'react';

const JOURNEY_STYLES = `
  .journey-roadmap {
    position: relative;
    padding: 32px 20px 24px;
    overflow: hidden;
  }

  /* Animated background grid */
  .journey-roadmap::before {
    content: '';
    position: absolute; inset: 0;
    background-image:
      linear-gradient(rgba(245,158,11,0.04) 1px, transparent 1px),
      linear-gradient(90deg, rgba(245,158,11,0.04) 1px, transparent 1px);
    background-size: 32px 32px;
    mask-image: radial-gradient(ellipse 80% 80% at 50% 50%, black 20%, transparent 100%);
    pointer-events: none;
  }

  /* Header */
  .journey-header {
    display: flex; align-items: center; justify-content: space-between;
    margin-bottom: 8px; gap: 12px; flex-wrap: wrap;
  }
  .journey-title-block {
    display: flex; align-items: center; gap: 12px;
  }
  .journey-icon-wrap {
    width: 48px; height: 48px; border-radius: 14px;
    display: flex; align-items: center; justify-content: center;
    background: linear-gradient(135deg, rgba(245,158,11,0.2), rgba(124,58,237,0.15));
    border: 1px solid rgba(245,158,11,0.25);
    font-size: 1.5rem;
    position: relative;
  }
  .journey-icon-wrap::after {
    content: ''; position: absolute; inset: -2px;
    border-radius: 16px;
    background: conic-gradient(from 0deg, rgba(245,158,11,0.3), transparent, rgba(124,58,237,0.3), transparent);
    animation: journey-icon-spin 8s linear infinite;
    z-index: -1; filter: blur(4px);
  }
  @keyframes journey-icon-spin {
    from { transform: rotate(0deg); }
    to { transform: rotate(360deg); }
  }
  .journey-title {
    font-family: var(--heading-font);
    font-size: 1.15rem; font-weight: 800;
    color: var(--pearl); line-height: 1.2;
  }
  .journey-subtitle {
    font-size: 0.78rem; color: var(--muted);
    margin-top: 2px;
  }
  .journey-period-badge {
    display: inline-flex; align-items: center; gap: 6px;
    padding: 6px 14px; border-radius: 999px;
    font-family: var(--mono-font);
    font-size: 0.72rem; font-weight: 600;
    color: #FCD34D; letter-spacing: 0.04em;
    background: rgba(245,158,11,0.1);
    border: 1px solid rgba(245,158,11,0.25);
  }

  /* Journey narrative */
  .journey-narrative {
    font-size: 0.85rem; color: var(--muted); line-height: 1.7;
    margin-bottom: 28px; max-width: 600px;
  }

  /* SVG roadmap */
  .journey-svg-wrap {
    position: relative;
    width: 100%;
    margin-bottom: 20px;
  }
  .journey-svg {
    width: 100%;
    height: auto;
    overflow: visible;
  }

  /* Path animation */
  .journey-path-bg {
    stroke: rgba(255,255,255,0.04);
    stroke-width: 3;
    fill: none;
    stroke-linecap: round;
  }
  .journey-path-active {
    stroke: url(#journeyGradient);
    stroke-width: 3;
    fill: none;
    stroke-linecap: round;
    stroke-dasharray: var(--path-length);
    stroke-dashoffset: var(--path-offset);
    transition: stroke-dashoffset 2s cubic-bezier(0.22, 1, 0.36, 1);
    filter: drop-shadow(0 0 6px rgba(245,158,11,0.4));
  }

  /* Milestone nodes */
  .journey-node {
    cursor: default;
    transition: transform 0.3s ease;
  }
  .journey-node:hover {
    transform: scale(1.15);
  }
  .journey-node-ring {
    transition: all 0.6s cubic-bezier(0.22, 1, 0.36, 1);
  }
  .journey-node-ring.active {
    filter: drop-shadow(0 0 12px var(--node-color));
  }

  /* Node labels */
  .journey-node-label {
    opacity: 0;
    transform: translateY(4px);
    transition: opacity 0.5s ease 0.3s, transform 0.5s ease 0.3s;
  }
  .journey-node-label.active {
    opacity: 1;
    transform: translateY(0);
  }

  /* Tooltip cards that appear below nodes */
  .journey-tooltip-row {
    display: grid;
    grid-template-columns: repeat(auto-fit, minmax(140px, 1fr));
    gap: 10px;
    margin-top: 4px;
  }
  .journey-tooltip {
    padding: 14px 16px;
    border-radius: 14px;
    border: 1px solid var(--border-2);
    background: var(--surface-1);
    text-align: center;
    opacity: 0;
    transform: translateY(12px) scale(0.95);
    transition: all 0.6s cubic-bezier(0.22, 1, 0.36, 1);
    position: relative;
    overflow: hidden;
  }
  .journey-tooltip.active {
    opacity: 1;
    transform: translateY(0) scale(1);
  }
  .journey-tooltip::before {
    content: '';
    position: absolute; top: 0; left: 0; right: 0;
    height: 2px;
    background: var(--tip-accent);
    opacity: 0;
    transition: opacity 0.4s ease 0.2s;
  }
  .journey-tooltip.active::before {
    opacity: 1;
  }
  .journey-tooltip:hover {
    border-color: rgba(245,158,11,0.3);
    box-shadow: 0 8px 24px rgba(0,0,0,0.2);
  }
  .journey-tip-emoji {
    font-size: 1.6rem;
    margin-bottom: 8px;
    display: block;
  }
  .journey-tip-title {
    font-family: var(--heading-font);
    font-size: 0.85rem; font-weight: 700;
    color: var(--pearl); margin-bottom: 3px;
  }
  .journey-tip-sub {
    font-size: 0.7rem; color: var(--muted);
    line-height: 1.4;
  }

  /* Bottom status bar */
  .journey-status {
    display: flex; align-items: center; gap: 12px;
    padding: 12px 16px; border-radius: 10px;
    border: 1px solid var(--border);
    background: var(--surface-1);
    margin-top: 16px;
  }
  .journey-status-dot {
    width: 8px; height: 8px; border-radius: 50%;
    background: #10B981;
    box-shadow: 0 0 8px rgba(16,185,129,0.6);
    animation: status-blink 2s ease-in-out infinite;
  }
  @keyframes status-blink {
    0%,100% { opacity: 1; }
    50% { opacity: 0.4; }
  }
  .journey-status-text {
    font-family: var(--mono-font);
    font-size: 0.72rem; color: var(--muted);
    letter-spacing: 0.03em;
  }
  .journey-status-text strong {
    color: #FCD34D; font-weight: 600;
  }

  /* Floating sparkle particles */
  .journey-sparkle {
    position: absolute;
    width: 3px; height: 3px;
    border-radius: 50%;
    background: #FCD34D;
    pointer-events: none;
    opacity: 0;
  }
  .journey-sparkle.active {
    animation: sparkle-float 2.5s ease-out forwards;
  }
  @keyframes sparkle-float {
    0% { opacity: 0; transform: translateY(0) scale(0); }
    20% { opacity: 1; transform: translateY(-10px) scale(1); }
    100% { opacity: 0; transform: translateY(-40px) scale(0); }
  }

  @media (max-width: 600px) {
    .journey-roadmap { padding: 24px 16px 20px; }
    .journey-tooltip-row { grid-template-columns: 1fr 1fr; }
    .journey-header { flex-direction: column; align-items: flex-start; }
  }
  @media (max-width: 400px) {
    .journey-tooltip-row { grid-template-columns: 1fr; }
  }
`;

const MILESTONES = [
  {
    id: 'start',
    emoji: '🚀',
    title: 'Left TCS',
    sub: 'Jun 2014',
    color: '#06B6D4',
    accent: 'linear-gradient(90deg, #06B6D4, #0891B2)',
  },
  {
    id: 'gate1',
    emoji: '📝',
    title: 'GATE 2015',
    sub: 'Qualified',
    color: '#A78BFA',
    accent: 'linear-gradient(90deg, #7C3AED, #A78BFA)',
  },
  {
    id: 'cgpsc',
    emoji: '🏛️',
    title: 'CGPSC Cleared',
    sub: 'Lecturer — Final Interview',
    color: '#10B981',
    accent: 'linear-gradient(90deg, #10B981, #34D399)',
  },
  {
    id: 'gate23',
    emoji: '🎯',
    title: 'GATE ×3',
    sub: '2015, 2016, 2017 — All Qualified',
    color: '#F59E0B',
    accent: 'linear-gradient(90deg, #F59E0B, #FCD34D)',
  },
  {
    id: 'mtech',
    emoji: '🎓',
    title: 'M.Tech @ MNNIT',
    sub: 'Secured via GATE 2017',
    color: '#EC4899',
    accent: 'linear-gradient(90deg, #EC4899, #F9A8D4)',
  },
];

const JourneyRoadmap = () => {
  const [isVisible, setIsVisible] = useState(false);
  const [activeCount, setActiveCount] = useState(0);
  const wrapRef = useRef(null);
  const pathRef = useRef(null);
  const [pathLength, setPathLength] = useState(0);
  const sparklesRef = useRef([]);

  // IntersectionObserver to trigger when visible
  useEffect(() => {
    const el = wrapRef.current;
    if (!el) return;
    const io = new IntersectionObserver(
      ([entry]) => {
        if (entry.isIntersecting) {
          setIsVisible(true);
          io.disconnect();
        }
      },
      { threshold: 0.3 }
    );
    io.observe(el);
    return () => io.disconnect();
  }, []);

  // Get path length after mount
  useEffect(() => {
    if (pathRef.current) {
      setPathLength(pathRef.current.getTotalLength());
    }
  }, []);

  // Sequentially activate milestones
  useEffect(() => {
    if (!isVisible) return;
    let count = 0;
    const timer = setInterval(() => {
      count++;
      setActiveCount(count);
      if (count >= MILESTONES.length) clearInterval(timer);
    }, 500);
    return () => clearInterval(timer);
  }, [isVisible]);

  // Generate sparkle positions
  useEffect(() => {
    sparklesRef.current = Array.from({ length: 12 }, () => ({
      left: 10 + Math.random() * 80,
      top: 10 + Math.random() * 60,
      delay: Math.random() * 3,
      size: 2 + Math.random() * 2,
    }));
  }, []);

  const progressPct = isVisible ? activeCount / MILESTONES.length : 0;
  const dashOffset = pathLength * (1 - progressPct);

  // Node positions along the SVG viewBox (600 × 100)
  const nodePositions = [
    { x: 40, y: 50 },
    { x: 170, y: 30 },
    { x: 300, y: 60 },
    { x: 430, y: 25 },
    { x: 560, y: 50 },
  ];

  return (
    <>
      <style>{JOURNEY_STYLES}</style>
      <div ref={wrapRef} className="journey-roadmap">
        {/* Floating sparkles */}
        {sparklesRef.current.map((s, i) => (
          <div
            key={i}
            className={`journey-sparkle${isVisible ? ' active' : ''}`}
            style={{
              left: `${s.left}%`,
              top: `${s.top}%`,
              width: s.size,
              height: s.size,
              animationDelay: `${s.delay + 1}s`,
              animationDuration: `${2 + Math.random() * 2}s`,
              animationIterationCount: 'infinite',
            }}
          />
        ))}

        {/* Header */}
        <div className="journey-header">
          <div className="journey-title-block">
            <div className="journey-icon-wrap">🏆</div>
            <div>
              <div className="journey-title">Career Growth Phase</div>
              <div className="journey-subtitle">
                Competitive exams · Govt. job success · NIT admission
              </div>
            </div>
          </div>
          <div className="journey-period-badge">
            <span style={{ color: '#10B981', fontSize: '0.5rem' }}>●</span>
            Jun 2014 → Jul 2017
          </div>
        </div>

        {/* Narrative */}
        <p className="journey-narrative">
          After TCS, I dedicated three years to competitive exam preparation —
          qualifying <strong style={{ color: '#FCD34D' }}>GATE three consecutive years</strong>,
          clearing the <strong style={{ color: '#34D399' }}>CGPSC State Lecturer exam</strong> (reached final interview),
          and securing admission to <strong style={{ color: '#67E8F9' }}>M.Tech at MNNIT Allahabad</strong>.
        </p>

        {/* SVG Roadmap */}
        <div className="journey-svg-wrap">
          <svg
            className="journey-svg"
            viewBox="0 0 600 90"
            preserveAspectRatio="xMidYMid meet"
          >
            <defs>
              <linearGradient id="journeyGradient" x1="0%" y1="0%" x2="100%" y2="0%">
                <stop offset="0%" stopColor="#06B6D4" />
                <stop offset="25%" stopColor="#7C3AED" />
                <stop offset="50%" stopColor="#10B981" />
                <stop offset="75%" stopColor="#F59E0B" />
                <stop offset="100%" stopColor="#EC4899" />
              </linearGradient>
              <filter id="nodeGlow">
                <feGaussianBlur stdDeviation="3" result="blur" />
                <feMerge>
                  <feMergeNode in="blur" />
                  <feMergeNode in="SourceGraphic" />
                </feMerge>
              </filter>
            </defs>

            {/* Background path */}
            <path
              d={`M ${nodePositions.map(p => `${p.x},${p.y}`).join(' L ')}`}
              className="journey-path-bg"
            />

            {/* Animated active path */}
            <path
              ref={pathRef}
              d={`M ${nodePositions.map(p => `${p.x},${p.y}`).join(' L ')}`}
              className="journey-path-active"
              style={{
                '--path-length': pathLength,
                '--path-offset': dashOffset,
              }}
            />

            {/* Milestone nodes */}
            {nodePositions.map((pos, i) => {
              const active = i < activeCount;
              const ms = MILESTONES[i];
              return (
                <g key={ms.id} className="journey-node">
                  {/* Outer pulse ring */}
                  {active && (
                    <circle
                      cx={pos.x} cy={pos.y} r="16"
                      fill="none"
                      stroke={ms.color}
                      strokeWidth="1"
                      opacity="0.3"
                    >
                      <animate
                        attributeName="r" values="14;20;14"
                        dur="2.5s" repeatCount="indefinite"
                      />
                      <animate
                        attributeName="opacity" values="0.4;0;0.4"
                        dur="2.5s" repeatCount="indefinite"
                      />
                    </circle>
                  )}

                  {/* Node circle */}
                  <circle
                    className={`journey-node-ring${active ? ' active' : ''}`}
                    cx={pos.x} cy={pos.y}
                    r={active ? 12 : 8}
                    fill={active ? ms.color : 'rgba(255,255,255,0.06)'}
                    stroke={active ? ms.color : 'rgba(255,255,255,0.1)'}
                    strokeWidth={active ? 2 : 1}
                    style={{ '--node-color': ms.color }}
                    filter={active ? 'url(#nodeGlow)' : undefined}
                  />

                  {/* Emoji inside */}
                  <text
                    x={pos.x} y={pos.y + 1}
                    textAnchor="middle" dominantBaseline="central"
                    fontSize={active ? '12' : '8'}
                    style={{
                      opacity: active ? 1 : 0.3,
                      transition: 'all 0.5s ease',
                    }}
                  >
                    {ms.emoji}
                  </text>
                </g>
              );
            })}
          </svg>
        </div>

        {/* Tooltip cards row */}
        <div className="journey-tooltip-row">
          {MILESTONES.map((ms, i) => (
            <div
              key={ms.id}
              className={`journey-tooltip${i < activeCount ? ' active' : ''}`}
              style={{
                transitionDelay: `${i * 0.15}s`,
                '--tip-accent': ms.accent,
              }}
            >
              <span className="journey-tip-emoji">{ms.emoji}</span>
              <div className="journey-tip-title">{ms.title}</div>
              <div className="journey-tip-sub">{ms.sub}</div>
            </div>
          ))}
        </div>

        {/* Status bar */}
        <div className="journey-status">
          <div className="journey-status-dot" />
          <div className="journey-status-text">
            Result → <strong>3× GATE qualified</strong> · <strong>Govt. exam cleared</strong> · <strong>NIT admission secured</strong>
          </div>
        </div>
      </div>
    </>
  );
};

export default JourneyRoadmap;
